def adjacent(adj, u, v):
    return u != v and ((adj >> (u*16 + v)) & 1) == 1

def lcn_color(adj, u, v):
    for w in range(16):
        if adjacent(adj, u, w) and adjacent(adj, v, w):
            return w
    return None

def has_k4(adj, n):
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                for d in range(c+1, n):
                    if (adjacent(adj,a,b) and adjacent(adj,a,c) and adjacent(adj,a,d)
                            and adjacent(adj,b,c) and adjacent(adj,b,d)
                            and adjacent(adj,c,d)):
                        return True
    return False

def has_mono_triangle(adj, n):
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                c01 = lcn_color(adj, a, b)
                c02 = lcn_color(adj, a, c)
                c12 = lcn_color(adj, b, c)
                if c01 is not None and c01 == c02 and c01 == c12:
                    return True
    return False

def verify(n_max):
    if not isinstance(n_max, int) or n_max < 4 or n_max > 6:
        return False
    for n in range(4, n_max + 1):
        pairs = []
        for u in range(n):
            for v in range(u+1, n):
                pairs.append((u, v))
        for mask in range(1 << len(pairs)):
            adj = 0
            for i in range(len(pairs)):
                if (mask >> i) & 1:
                    adj = adj | (1 << (pairs[i][0]*16 + pairs[i][1]))
            if has_mono_triangle(adj, n) and not has_k4(adj, n):
                return False
    return True

def main():
    return verify(6)
